package com.franco.desco.adapter.in.web.campaign;import com.franco.desco.application.campaign.*;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.campaign.CampaignModels;import org.springframework.stereotype.Component;import java.time.LocalDate;
@Component public class CampaignWebMapper{public CampaignCommands.ListCampaigns list(int p,int t,String estado,Long asociacion,Long comprador,LocalDate desde,LocalDate hasta){return new CampaignCommands.ListCampaigns(new PageRequest<>(p,t,new CampaignCommands.Filter(estado,asociacion,comprador,desde,hasta),null,null));}public CampaignResponses.Summary response(CampaignModels.Summary x){return new CampaignResponses.Summary(x.campaniaVentaId(),x.codigo(),x.nombre(),x.fechaInicio(),x.fechaFin(),x.estadoProceso(),x.asociacionId(),x.asociacion(),x.empresaCompradoraId(),x.comprador(),x.observacion(),x.participantesActivos(),x.operativos());}public CampaignResponses.Detail response(CampaignModels.Detail x){return new CampaignResponses.Detail(response(x.campania()),x.participantes().stream().map(p->new CampaignResponses.Participant(p.participacionId(),p.estadoParticipacion(),p.socioId(),p.numeroDocumento(),p.socioNombre())).toList(),x.operativos().stream().map(o->new CampaignResponses.Operation(o.operativoVentaId(),o.codigo(),o.fechaInicioProgramada(),o.fechaFinProgramada(),o.fechaInicioReal(),o.fechaFinReal(),o.cantidadJabasRecibidas(),o.estadoProceso(),o.observacion())).toList(),x.precios().stream().map(p->new CampaignResponses.Price(p.precioComercialId(),p.operativoVentaId(),p.variedadPaltaId(),p.condicionComercialId(),p.precio(),p.moneda(),p.unidadMedida(),p.fechaVigenciaDesde(),p.fechaVigenciaHasta(),p.version())).toList());}}
